48	export function parseCancelRequest(body: unknown): CancelOrderRequest {
49	  if (body === undefined || body === null) {
50	    return {};
51	  }
52	  if (!isJsonObject(body)) {
53	    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
54	  }
55	  const reader = new InputReader(body);
56	  const reason = reader.optionalString("reason");
57	  if (reason !== undefined && reason.length > 200) {
58	    reader.fail("reason", "must be at most 200 characters");
59	  }
